        sse_encode_String(hubName, serializer);
      case SessionEvent_Disconnected(reason: final reason):
        sse_encode_i_32(1, serializer);
        sse_encode_String(reason, serializer);
      case SessionEvent_Roster(members: final members):
        sse_encode_i_32(2, serializer);
